import{z as p,x as A,o as r,c as d,q as l,j as n,D as E,d as t,s as i,S as o,b as a}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"亮度、照度与光学扩展量预备","description":"","frontmatter":{"title":"亮度、照度与光学扩展量预备","date":"2026-09-10T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/photometry-etendue-prep.md","filePath":"litho/photometry-etendue-prep.md","lastUpdated":1791413859000}'),m={name:"litho/photometry-etendue-prep.md"};function B(h,e,u,D,c,f){const s=A("Mermaid");return r(),d("div",null,[e[2]||(e[2]=l('<h1 id="亮度、照度与光学扩展量预备" tabindex="-1">亮度、照度与光学扩展量预备 <a class="header-anchor" href="#亮度、照度与光学扩展量预备" aria-label="Permalink to &quot;亮度、照度与光学扩展量预备&quot;">​</a></h1><div class="epigraph"><p>亮度沿无损光路守恒；光学扩展量把光源面积与立体角绑在一起，限制能耦合进光瞳的功率，开大 NA 并不能无中生有地造光子。</p><footer>—— 据 Born &amp; Wolf, Principles of Optics 对辐射度学与 Lagrange 不变量的整理</footer></div><p><a href="/litho/geometric-aberration-tour">上一课</a>说明真实透镜有像差。本课不重列 Seidel。缺口是：光源有多亮、晶圆上能有多少功率、为何大孔径与高通量会打架？后课光源收集、匀光与扫描速度，都要碰辐射度与 étendue。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/litho/stop-pupil-fov">光阑、光瞳与视场</a> 决定角度范围，但不保证有足够光子。曝光要的是剂量（能量/面积）；剂量 = 照度 × 时间。若光源的光学扩展量大于系统能接受的量，多出来的亮度进不了瞳，功率被丢掉。没有亮度、照度、étendue 三个词，无法读「源–光瞳–晶圆」链上的功率瓶颈。缺口是几何辐射度，不是再修一阶像差。</p><h3 id="亮度不是照度" tabindex="-1">亮度不是照度 <a class="header-anchor" href="#亮度不是照度" aria-label="Permalink to &quot;亮度不是照度&quot;">​</a></h3><p>照度 \\(E\\)：单位面积接收的功率。亮度 \\(L\\)：单位面积、单位立体角的功率。同一光源，用大立体角去收，照度可以变大，亮度在无损折射下不变。把「更亮」和「晶圆上更亮」混用，会以为加大 NA 总能按立体角线性涨剂量；光学扩展量守恒时，往往只是把同一批光子换一个锥角。</p><p><span class="marginnote">étendue \\(G\\sim A\\Omega\\)（面积 × 立体角）。近轴还有拉格朗日不变量 \\(n h \\theta\\)。无损、无挡光时 \\(G\\) 沿光路守恒。吸收、散射与挡光会减小可用 \\(G\\)。</span></p><p><span class="marginnote">étendue 可以想象成水管的粗细：水源再猛，管口就那么大，单位时间能过去的水有上限。它把「发光面积」和「发光张角」捆在一起算——只增大面积或只增大张角，\\(G\\) 都变大；想塞进光瞳，两个维度得一起凑。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>理想无损光路：亮度 \\(L\\) 守恒（相对折射率变化时用 \\(L/n^2\\) 的形式，本课先记「不能无中生有」）。像方照度大约 \\(E\\sim L\\,\\Omega_{\\mathrm{pupil}}\\)，\\(\\Omega_{\\mathrm{pupil}}\\) 与 NA 相关。源侧 \\(G_s\\sim A_s\\Omega_s\\)；系统 \\(G_{\\mathrm{sys}}\\) 由入瞳大小与接受角决定。\\(G_s\\le G_{\\mathrm{sys}}\\) 才能把源用满；否则必须整形、挡光或接受损失。</p><p>扫描狭缝把瞬时照明面积切小，étendue 预算要按狭缝而不是按全场算。照度够高才能在给定扫描速度下凑够剂量；速度又决定产能。于是源、瞳、狭缝、扫描是同一条功率链。本课只把链写清，不进入某一代光源的等离子体参数。</p><p>扫描曝光：狭缝内照度乘扫描速度得到线剂量。放大率 \\(|M|\\) 把物方功率密度换成像方功率密度。本课只把账本写清，不进入光源等离子体物理。</p><p><span class="marginnote">数字实例：若晶圆照度是 \\(10\\ \\mathrm{mW/cm^2}\\)，抗蚀剂需要 \\(20\\ \\mathrm{mJ/cm^2}\\) 剂量，静止曝光就要 \\(20\\div 10=2\\) 秒；想要 1 秒完成，就得把照度翻倍或把亮度链上的某处损失补回来——这正是本课功率账的用处。</span></p><p><span class="marginnote">辐射度量与光度学单位不同：本课用功率（W），不用流明。光刻剂量是能量密度，跟视觉明暗无关。</span></p>',15)),(r(),n(o,null,{default:E(()=>[i(s,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22%E5%85%89%E6%BA%90%E9%9D%A2%E7%A7%AF%E4%B8%8E%E7%AB%8B%E4%BD%93%E8%A7%92%22%5D%20--%3E%20ET%5B%22%E5%85%89%E5%AD%A6%E6%89%A9%E5%B1%95%E9%87%8F%20G%22%5D%0A%20%20ET%20--%3E%20PUPIL%5B%22%E5%85%A5%E7%9E%B3%E5%8F%AF%E6%8E%A5%E5%8F%97%E7%9A%84%20G%22%5D%0A%20%20PUPIL%20--%3E%20L%5B%22%E4%BA%AE%E5%BA%A6%E5%AE%88%E6%81%92%22%5D%0A%20%20L%20--%3E%20E%5B%22%E6%99%B6%E5%9C%86%E7%85%A7%E5%BA%A6%22%5D%0A%20%20E%20--%3E%20DOSE%5B%22%E5%89%82%E9%87%8F%E7%AD%89%E4%BA%8E%E7%85%A7%E5%BA%A6%E4%B9%98%E6%97%B6%E9%97%B4%22%5D%0A"})]),fallback:E(()=>[...e[0]||(e[0]=[t(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a("h2",{id:"机制",tabindex:"-1"},[t("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=a("p",null,"准分子激光源 étendue 相对小，较容易填满高 NA 瞳。放电或激光等离子体类源 étendue 大，收集光学只能截一块，通量长期受限于此——本课给守恒逻辑，不把某代机台拆开。照明中继把源成像到光瞳，积分棒或微透镜阵列把照度匀开，使视场内剂量均匀；均匀度是视场课的功率版补充。",-1)),e[5]||(e[5]=a("p",null,[t("像差与挡光减小有效 \\(G\\) 或局部亮度。本课把它们看成损耗项，不回头重做 Seidel 分类。下一课 "),a("a",{href:"/litho/coherence-length-prep"},"相干长度与光源带宽预备"),t(" 问谱宽，与本课的「有多少功率」正交：窄带改善相干与色差，却可能丢掉源功率。")],-1)),e[6]||(e[6]=a("p",null,"匀光之后，晶圆上要的是照度均匀，而不是源面长什么样。源的结构被中继与积分元件抹掉，只留下亮度与 étendue 是否匹配。若 \\(G_s\\) 过大，多出来的是进不了瞳的光，会变成热与杂散光，不增加剂量。这就是「收集效率」在辐射度语言里的意思：不是源不亮，是系统装不下。",-1)),(r(),n(o,null,{default:E(()=>[i(s,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E6%BA%90%E6%89%A9%E5%B1%95%E9%87%8F%20Gs%20%E4%B8%8E%E7%B3%BB%E7%BB%9F%20Gsys%20%E6%AF%94%22%7D%20--%20%22Gs%20%E5%B0%8F%E4%BA%8E%E7%AD%89%E4%BA%8E%20Gsys%22%20--%3E%20FULL%5B%22%E6%BA%90%E7%94%A8%E6%BB%A1%20%E7%85%A7%E5%BA%A6%E8%83%BD%E6%8B%89%E9%AB%98%22%5D%0A%20%20Q%20--%20%22Gs%20%E5%A4%A7%E4%BA%8E%20Gsys%22%20--%3E%20CLIP%5B%22%E5%A4%9A%E4%BD%99%E7%9A%84%E5%85%89%E8%BF%9B%E4%B8%8D%E4%BA%86%E7%9E%B3%22%5D%0A%20%20CLIP%20--%3E%20H%5B%22%E5%8F%98%E6%88%90%E7%83%AD%E4%B8%8E%E6%9D%82%E6%95%A3%E5%85%89%22%5D%0A%20%20CLIP%20--%3E%20S%5B%22%E6%88%96%E6%95%B4%E5%BD%A2%E5%90%8E%E5%8F%AA%E7%94%A8%E4%B8%80%E5%B0%8F%E5%9D%97%22%5D%0A%20%20FULL%20--%3E%20D%5B%22%E5%89%82%E9%87%8F%20%3D%20%E7%85%A7%E5%BA%A6%20%C3%97%20%E6%97%B6%E9%97%B4%22%5D%0A%20%20S%20--%3E%20D%0A"})]),fallback:E(()=>[...e[1]||(e[1]=[t(" Loading... ",-1)])]),_:1})),e[7]||(e[7]=l('<p><span class="marginnote">常见误区：以为「换更亮的灯」总能加快曝光。若源的 étendue 超过光瞳能装下的量，多出来的亮度根本进不了系统，只会在光学件上发热、在像面上添杂散光——花钱买了光子，又亲手把它们扔了。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课几何辐射度；干涉条纹对比度另算。相干光的「亮度」要部分相干修正，下一课衔接。也不把 étendue 写成 CD。抗蚀剂要多少 mJ/cm² 是材料响应，本课只提供到达晶圆的照度语言。</p><p>杂散光与挡光会在守恒之外再吃一块功率，表现为有效亮度下降。后课默认：亮度沿无损光路守恒；剂量由照度与时间相乘；源–瞳耦合受 étendue 限制。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>亮度沿无损光路守恒；照度随接受立体角变。</li><li>光学扩展量 \\(A\\Omega\\) 限制源能进多少瞳；大 NA 不自动等于更多光子。</li><li>剂量 = 照度 × 时间；扫描通量与此绑定。</li><li>带宽与相干是下一课，与功率账本分开。</li><li>出处：Born &amp; Wolf, <em>Principles of Optics</em>；Hecht, <em>Optics</em>。</li></ul>',6))])}const g=p(m,[["render",B]]);export{P as __pageData,g as default};
